-- Removal of idempotency scope/fingerprints, immutable audit or outbox leases must break these behaviors.
begin;
create extension if not exists pgtap with schema extensions;
grant usage on schema extensions to cuevo_api,cuevo_worker;
set local search_path = extensions, pg_catalog;
select no_plan();
-- Isolate queue fixtures from prior synthetic API runs; rollback restores existing events.
delete from app.habit_observations;delete from app.learner_signals;delete from app.learner_state_snapshots;delete from internal.processed_events;delete from internal.outbox_events;
set local role cuevo_api;
select set_config('app.actor_id','20000000-0000-4000-8000-000000000001',true);
select set_config('app.school_id','10000000-0000-4000-8000-000000000001',true);
select is((internal.begin_command('request-1','school.update','0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef')->>'state'),'NEW','first command claims one idempotency record');
select is((internal.begin_command('request-1','school.update','0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef')->>'state'),'IN_PROGRESS','duplicate pending command does not claim again');
select throws_ok($$select internal.begin_command('request-1','school.update','ffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffff')$$,'22023',null,'idempotency key reuse with different input is rejected');
select lives_ok($$select internal.finish_command('request-1','school.update','0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef','{"ok":true}'::jsonb)$$,'successful command stores replay response');
select is((internal.begin_command('request-1','school.update','0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef')->>'state'),'COMPLETED','completed command replay returns stored outcome');
select is((internal.begin_command('request-1','school.update','0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef')->'response'->>'ok'),'true','replay retains response');
select throws_ok($$select internal.finish_command('request-1','school.update','0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef','{"ok":false}'::jsonb)$$,'22023',null,'completed response cannot be overwritten');
select throws_ok($$select internal.finish_command('request-1','school.update',null,'{"ok":true}'::jsonb)$$,'22023',null,'missing fingerprint cannot acknowledge command');
select lives_ok($$select internal.append_audit('school.updated','school','10000000-0000-4000-8000-000000000001','request-1','succeeded','{}'::jsonb)$$,'authorized command can append audit');
select lives_ok($$select internal.enqueue_event('school.updated','school','10000000-0000-4000-8000-000000000001',1,'{}'::jsonb,'event-1')$$,'authorized command enqueues event');
select lives_ok($$select internal.enqueue_event('school.updated','school','10000000-0000-4000-8000-000000000001',1,'{}'::jsonb,'event-1')$$,'same outbox event deduplicates');
select throws_ok($$select internal.enqueue_event('school.updated','school','10000000-0000-4000-8000-000000000001',1,'{"different":true}'::jsonb,'event-1')$$,'22023',null,'different event payload cannot reuse deduplication key');
select throws_ok('select * from internal.audit_events','42501',null,'API cannot enumerate raw audit');
select throws_ok('update internal.audit_events set action=''tampered''','42501',null,'API cannot update audit');
select throws_ok('delete from internal.audit_events','42501',null,'API cannot delete audit');
reset role;
select is((select count(*) from internal.outbox_events where deduplication_key='event-1'),1::bigint,'duplicate publication stores one event');
select throws_ok('update internal.audit_events set action=''tampered''','55000',null,'audit immutable even for owner connection');
select throws_ok('delete from internal.audit_events','55000',null,'audit deletion cannot bypass immutable trigger');
set local role cuevo_worker;
select throws_ok('select * from internal.claim_outbox(null,30)','22023',null,'unbounded null batch is rejected');
select throws_ok('select * from internal.claim_outbox(1,null)','22023',null,'missing lease lifetime is rejected');
select throws_ok($$select internal.fail_outbox('99999999-0000-4000-8000-000000000001','99999999-0000-4000-8000-000000000002','TIMEOUT',null)$$,'22023',null,'missing retry bound is rejected');
select throws_ok('select * from app.people','42501',null,'worker has no learner-table privileges');
select throws_ok('select * from internal.outbox_events','42501',null,'worker has no raw outbox privilege');
select is((select count(*) from internal.claim_outbox(10,30)),1::bigint,'worker atomically leases pending event');
select is((select count(*) from internal.claim_outbox(10,30)),0::bigint,'leased event cannot be claimed twice');
select is(internal.complete_outbox('99999999-0000-4000-8000-000000000001','99999999-0000-4000-8000-000000000002'),false,'unknown lease acknowledgement fails');
reset role;
create temporary table claimed_event as select id,lease_token from internal.outbox_events where deduplication_key='event-1';
grant select on claimed_event to cuevo_worker;
set local role cuevo_worker;
select is(internal.fail_outbox((select id from claimed_event),(select lease_token from claimed_event),'PROVIDER_TIMEOUT',0),true,'bounded retry returns event to pending');
select is((select count(*) from internal.claim_outbox(10,30)),1::bigint,'retry can obtain a fresh lease');
select is(internal.complete_outbox((select id from claimed_event),(select lease_token from claimed_event)),false,'stale lease token cannot acknowledge event');
reset role;
update claimed_event set lease_token=(select lease_token from internal.outbox_events where deduplication_key='event-1');
set local role cuevo_worker;
select is(internal.complete_outbox((select id from claimed_event),(select lease_token from claimed_event)),true,'current lease completes event');
select is((select count(*) from internal.claim_outbox(10,30)),0::bigint,'completed event is not delivered again');
reset role;
select is((select attempt_count from internal.outbox_events where deduplication_key='event-1'),2,'retry attempts recorded');

set local role cuevo_api;
savepoint failed_academic_command;
select internal.begin_command('rolled-back','school.update','0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef');
select internal.append_audit('school.updated','school','10000000-0000-4000-8000-000000000001','rolled-back','succeeded','{}'::jsonb);
select internal.enqueue_event('school.updated','school','10000000-0000-4000-8000-000000000001',1,'{}'::jsonb,'rolled-back');
rollback to failed_academic_command;
reset role;
select is((select count(*) from internal.idempotency_keys where key='rolled-back'),0::bigint,'failed transaction rolls back command reservation');
select is((select count(*) from internal.audit_events where request_id='rolled-back'),0::bigint,'failed transaction leaves no partial audit');
select is((select count(*) from internal.outbox_events where deduplication_key='rolled-back'),0::bigint,'failed transaction leaves no orphan event');
set local role cuevo_api;
select internal.enqueue_event('school.updated','school','10000000-0000-4000-8000-000000000001',1,'{}'::jsonb,'bounded-retry');
reset role;
update claimed_event set id=(select id from internal.outbox_events where deduplication_key='bounded-retry'),lease_token=null;
set local role cuevo_worker;
select is((select count(*) from internal.claim_outbox(1,5)),1::bigint,'first bounded-retry delivery is leased');
reset role;
update internal.outbox_events set lease_until=clock_timestamp()-interval '1 second' where deduplication_key='bounded-retry';
update claimed_event set lease_token=(select lease_token from internal.outbox_events where deduplication_key='bounded-retry');
set local role cuevo_worker;
select is(internal.complete_outbox((select id from claimed_event),(select lease_token from claimed_event)),false,'expired lease cannot complete event');
select is((select count(*) from internal.claim_outbox(1,5)),1::bigint,'expired lease is safely reclaimed');
reset role;
update internal.outbox_events set attempt_count=5 where deduplication_key='bounded-retry';
update claimed_event set lease_token=(select lease_token from internal.outbox_events where deduplication_key='bounded-retry');
set local role cuevo_worker;
select is(internal.fail_outbox((select id from claimed_event),(select lease_token from claimed_event),'MAX_RETRIES',0),true,'last allowed failure completes bounded retry transition');
select is((select count(*) from internal.claim_outbox(10,30)),0::bigint,'exhausted retry event cannot be leased again');
reset role;
select is((select state from internal.outbox_events where deduplication_key='bounded-retry'),'FAILED','exhausted event remains inspectable in failed state');
select * from finish();
rollback;
